package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonWriter_value_TriageGen1Test {

    @Test
    public void testValue_true() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter()) {
            @Override
            public void writeDeferredName() throws IOException {}
            @Override
            public void beforeValue(boolean value) throws IOException {}
        };
        jsonWriter.value(true);
        assertEquals("true", jsonWriter.out.toString());
    }

    @Test
    public void testValue_false() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter()) {
            @Override
            public void writeDeferredName() throws IOException {}
            @Override
            public void beforeValue(boolean value) throws IOException {}
        };
        jsonWriter.value(false);
        assertEquals("false", jsonWriter.out.toString());
    }

    @Test
    public void testValue_null() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter()) {
            @Override
            public void writeDeferredName() throws IOException {}
            @Override
            public void beforeValue(boolean value) throws IOException {}
        };
        try {
            jsonWriter.value(null);
            fail("Expected IOException");
        } catch (IOException e) {
            // Expected
        }
    }

    @Test
    public void testValue_boolean() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter()) {
            @Override
            public void writeDeferredName() throws IOException {}
            @Override
            public void beforeValue(boolean value) throws IOException {}
        };
        jsonWriter.value(true);
        assertTrue(jsonWriter.isLenient());
        assertFalse(jsonWriter.isHtmlSafe());
        assertFalse(jsonWriter.isSerializeNulls());
    }

    @Test
    public void testValue_boolean_setLenient() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.setLenient(true);
        jsonWriter.value(true);
        assertTrue(jsonWriter.isLenient());
        assertFalse(jsonWriter.isHtmlSafe());
        assertFalse(jsonWriter.isSerializeNulls());
    }

    @Test
    public void testValue_boolean_setHtmlSafe() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.setHtmlSafe(true);
        jsonWriter.value(true);
        assertFalse(jsonWriter.isLenient());
        assertTrue(jsonWriter.isHtmlSafe());
        assertFalse(jsonWriter.isSerializeNulls());
    }

    @Test
    public void testValue_boolean_setSerializeNulls() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.setSerializeNulls(true);
        jsonWriter.value(true);
        assertFalse(jsonWriter.isLenient());
        assertFalse(jsonWriter.isHtmlSafe());
        assertTrue(jsonWriter.isSerializeNulls());
    }
}
